(() => {
  'use strict';
  const byId=id=>document.getElementById(id);
  const form=byId('vp-form'),dialog=byId('vp-dialog');
  const state={csrf:'',coupons:[]};
  const rupees=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Number(value)||0);
  const date=value=>value?new Date(String(value).replace(' ','T')+'Z').toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'—';
  const inputDate=value=>value?new Date(String(value).replace(' ','T')+'Z').toISOString().slice(0,16):'';
  async function api(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch('../../../api/vendor/'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Coupon request failed.');return data;}
  function message(text,error=false){const node=byId('vp-summary');node.textContent=text;node.className='vc-status '+(error?'warning':'info');}
  function cell(row,text){const td=document.createElement('td');td.textContent=String(text??'—');row.append(td);return td;}
  function draw(){const body=byId('vp-rows');body.replaceChildren();const active=state.coupons.filter(c=>c.status==='active').length;message(state.coupons.length+' coupons · '+active+' active');if(!state.coupons.length){const row=document.createElement('tr');const td=cell(row,'No coupons yet. Create your first coupon when your products are ready.');td.colSpan=7;body.append(row);return;}
    state.coupons.forEach(coupon=>{const row=document.createElement('tr');cell(row,coupon.code);cell(row,coupon.discount_type==='percent'?Number(coupon.discount_value)+'%':rupees(coupon.discount_value));cell(row,rupees(coupon.min_order_amount));cell(row,Number(coupon.redemption_count)+' / '+(coupon.usage_limit||'unlimited'));cell(row,date(coupon.starts_at)+' – '+date(coupon.ends_at));cell(row,coupon.status);const actions=document.createElement('td');const edit=document.createElement('button');edit.type='button';edit.className='vc-btn small';edit.textContent='Edit';edit.addEventListener('click',()=>open(coupon));actions.append(edit);if(coupon.status!=='archived'){const archive=document.createElement('button');archive.type='button';archive.className='vc-btn small';archive.textContent='Archive';archive.addEventListener('click',()=>archiveCoupon(coupon));actions.append(' ',archive);}row.append(actions);body.append(row);});}
  async function load(){try{const [identity,result]=await Promise.all([api('auth/me.php'),api('coupons.php')]);state.csrf=identity.csrf_token||'';state.coupons=result.coupons||[];draw();}catch(error){message(error.message,true);}}
  function open(coupon){form.reset();const names=['coupon_id','code','discount_type','discount_value','min_order_amount','max_discount_amount','usage_limit','per_customer_limit','status'];names.forEach(name=>{if(coupon&&coupon[name]!==null&&coupon[name]!==undefined)form.elements.namedItem(name).value=coupon[name];});if(coupon){form.elements.namedItem('coupon_id').value=coupon.id;form.elements.namedItem('starts_at').value=inputDate(coupon.starts_at);form.elements.namedItem('ends_at').value=inputDate(coupon.ends_at);}byId('vp-dialog-title').textContent=coupon?'Edit coupon':'Create coupon';dialog.showModal();}
  async function archiveCoupon(coupon){if(!confirm('Archive '+coupon.code+'? Customers will no longer be able to use it.'))return;try{await api('coupons.php?id='+encodeURIComponent(coupon.id),'DELETE');await load();}catch(error){message(error.message,true);}}
  byId('vp-new').addEventListener('click',()=>open(null));byId('vp-close').addEventListener('click',()=>dialog.close());
  form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));const start=new Date(data.starts_at),end=new Date(data.ends_at);if(!(end>start)){message('End time must be later than start time.',true);return;}if(data.discount_type==='percent'&&Number(data.discount_value)>100){message('Percentage cannot exceed 100%.',true);return;}const payload={...data,starts_at:start.toISOString(),ends_at:end.toISOString(),max_discount_amount:data.max_discount_amount===''?null:Number(data.max_discount_amount),usage_limit:data.usage_limit===''?null:Number(data.usage_limit)};const button=event.submitter;button.disabled=true;try{await api('coupons.php',data.coupon_id?'PATCH':'POST',payload);dialog.close();await load();}catch(error){message(error.message,true);}finally{button.disabled=false;}});
  load();
})();
